export const questions = {
  get general(){ return factBank; },
  get geography(){ return factBank.filter(q=>q.category==='Geografi'); },
  get sports(){ return factBank.filter(q=>q.category==='Sport'); },
  get fiveone(){ return specialBanks.fiveone; },
  get career(){ return specialBanks.career; },
  get music(){ return specialBanks.music; }
};
export const getDifficulty = (type,q,index) => ['easy','medium','hard'].includes(q?.difficulty) ? q.difficulty : 'medium';
